#include <emscripten.h>
#include <emscripten/bind.h>
#include <opencv2/core.hpp>
#include <opencv2/imgproc.hpp>
#include <opencv2/features2d.hpp>
#include <vector>
#include <array>
#include <algorithm>
#include <cmath>
#include <random>

// 返回给 JS 的姿态数据结构
struct ARPose {
    std::array<float, 16> transformMatrix;
    bool isTracking;
};

class ARTracker {
private:
    uint8_t* _pixelBuffer = nullptr;
    int _width;
    int _height;

    // OpenCV 核心组件
    cv::Mat _cameraMatrix;
    cv::Mat _cameraMatrixInv;
    cv::Ptr<cv::ORB> _orb;
    cv::Ptr<cv::BFMatcher> _matcher;

    // 酒标模板数据
    cv::Mat _targetDescriptors;
    std::vector<cv::KeyPoint> _targetKeypoints;
    int _targetWidth = 0;
    int _targetHeight = 0;

    // 物理参数（单位：米）
    float _physicalWidth = 0.10f;  // 默认酒标宽度 10 厘米
    float _physicalHeight = 0.15f; // 默认酒标高度 15 厘米

    // 极速 4 点 DLT (Direct Linear Transform) 算法：计算 2D 物理坐标到 2D 图像坐标的投影单应性矩阵 H
    cv::Mat computeHomographyDLT(const std::vector<cv::Point2f>& src, const std::vector<cv::Point2f>& dst) {
        cv::Mat A = cv::Mat::zeros(8, 9, CV_64F);
        for (int i = 0; i < 4; ++i) {
            double x = src[i].x;
            double y = src[i].y;
            double u = dst[i].x;
            double v = dst[i].y;

            // 单点 NaN/Inf 拦截
            if (std::isnan(x) || std::isinf(x) || std::isnan(y) || std::isinf(y) ||
                std::isnan(u) || std::isinf(u) || std::isnan(v) || std::isinf(v)) {
                return cv::Mat();
            }

            A.at<double>(2 * i, 0) = -x;
            A.at<double>(2 * i, 1) = -y;
            A.at<double>(2 * i, 2) = -1.0;
            A.at<double>(2 * i, 3) = 0.0;
            A.at<double>(2 * i, 4) = 0.0;
            A.at<double>(2 * i, 5) = 0.0;
            A.at<double>(2 * i, 6) = x * u;
            A.at<double>(2 * i, 7) = y * u;
            A.at<double>(2 * i, 8) = u;

            A.at<double>(2 * i + 1, 0) = 0.0;
            A.at<double>(2 * i + 1, 1) = 0.0;
            A.at<double>(2 * i + 1, 2) = 0.0;
            A.at<double>(2 * i + 1, 3) = -x;
            A.at<double>(2 * i + 1, 4) = -y;
            A.at<double>(2 * i + 1, 5) = -1.0;
            A.at<double>(2 * i + 1, 6) = x * v;
            A.at<double>(2 * i + 1, 7) = y * v;
            A.at<double>(2 * i + 1, 8) = v;
        }

        // ⚡ NaN/Inf 过滤：退化点对会导致 SVD 崩溃，必须在计算前拦截
        if (!cv::checkRange(A, true)) {
            return cv::Mat();
        }

        cv::Mat w, u, vt;
        cv::SVD::compute(A, w, u, vt);

        // SVD 结果可能因数值退化产生 NaN
        if (!cv::checkRange(vt, true)) {
            return cv::Mat();
        }

        // 奇异值分解 A = U * W * V^T，最后一列即为对应的齐次解（vt的最后一行）
        cv::Mat H = vt.row(8).reshape(1, 3);
        double h33 = H.at<double>(2, 2);
        if (std::abs(h33) > 1e-8) {
            H = H / h33;
        }
        return H;
    }

    // 自研 RANSAC 鲁棒性单应性过滤算法
    cv::Mat ransacHomography(const std::vector<cv::Point2f>& src, const std::vector<cv::Point2f>& dst, std::vector<int>& bestInliers, double threshold = 8.0) {
        int n = src.size();
        bestInliers.clear();
        if (n < 4) return cv::Mat();

        int maxIterations = 150; // 最大迭代次数
        int bestInliersCount = 0;
        cv::Mat bestH;

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, n - 1);

        for (int iter = 0; iter < maxIterations; ++iter) {
            std::vector<int> idx;
            while (idx.size() < 4) {
                int r = dis(gen);
                if (std::find(idx.begin(), idx.end(), r) == idx.end()) {
                    idx.push_back(r);
                }
            }

            std::vector<cv::Point2f> src_sample(4), dst_sample(4);
            for (int i = 0; i < 4; ++i) {
                src_sample[i] = src[idx[i]];
                dst_sample[i] = dst[idx[i]];
            }

            cv::Mat H = computeHomographyDLT(src_sample, dst_sample);
            if (H.empty()) continue;

            std::vector<int> currentInliers;
            for (int i = 0; i < n; ++i) {
                cv::Mat pt = (cv::Mat_<double>(3, 1) << src[i].x, src[i].y, 1.0);
                cv::Mat projected = H * pt;
                double w = projected.at<double>(2, 0);
                if (std::abs(w) < 1e-7) continue;

                double px = projected.at<double>(0, 0) / w;
                double py = projected.at<double>(1, 0) / w;

                double err = std::sqrt((px - dst[i].x) * (px - dst[i].x) + (py - dst[i].y) * (py - dst[i].y));
                if (err < threshold) {
                    currentInliers.push_back(i);
                }
            }

            if ((int)currentInliers.size() > bestInliersCount) {
                bestInliersCount = (int)currentInliers.size();
                bestInliers = currentInliers;
                bestH = H;
            }
        }

        // 精细化拟合：利用所有内点，重新最小二乘构建更精确的 H 矩阵
        if (bestInliersCount >= 6) {
            // 防止极端情况下 bestInliersCount 导致超大矩阵分配
            int refineRows = std::min(bestInliersCount, 200);
            cv::Mat A = cv::Mat::zeros(refineRows * 2, 9, CV_64F);

            int usedCount = 0;
            for (int i = 0; i < bestInliersCount; ++i) {
                int idx = bestInliers[i];
                double x = src[idx].x;
                double y = src[idx].y;
                double u = dst[idx].x;
                double v = dst[idx].y;

                // 单点 NaN/Inf 检查
                if (std::isnan(x) || std::isinf(x) || std::isnan(y) || std::isinf(y) ||
                    std::isnan(u) || std::isinf(u) || std::isnan(v) || std::isinf(v)) {
                    continue;
                }

                if (usedCount >= refineRows) break;

                A.at<double>(2 * usedCount, 0) = -x;
                A.at<double>(2 * usedCount, 1) = -y;
                A.at<double>(2 * usedCount, 2) = -1.0;
                A.at<double>(2 * usedCount, 3) = 0.0;
                A.at<double>(2 * usedCount, 4) = 0.0;
                A.at<double>(2 * usedCount, 5) = 0.0;
                A.at<double>(2 * usedCount, 6) = x * u;
                A.at<double>(2 * usedCount, 7) = y * u;
                A.at<double>(2 * usedCount, 8) = u;

                A.at<double>(2 * usedCount + 1, 0) = 0.0;
                A.at<double>(2 * usedCount + 1, 1) = 0.0;
                A.at<double>(2 * usedCount + 1, 2) = 0.0;
                A.at<double>(2 * usedCount + 1, 3) = -x;
                A.at<double>(2 * usedCount + 1, 4) = -y;
                A.at<double>(2 * usedCount + 1, 5) = -1.0;
                A.at<double>(2 * usedCount + 1, 6) = x * v;
                A.at<double>(2 * usedCount + 1, 7) = y * v;
                A.at<double>(2 * usedCount + 1, 8) = v;
                usedCount++;
            }

            if (usedCount < 4) {
                // 有效内点不足，保持之前的 bestH
                return bestH;
            }

            if (!cv::checkRange(A, true)) {
                return bestH;
            }

            cv::Mat w, u, vt;
            cv::SVD::compute(A.rowRange(0, usedCount * 2), w, u, vt);
            // 检查 SVD 结果
            if (!cv::checkRange(u, true) || !cv::checkRange(vt, true)) {
                return bestH;
            }
            bestH = vt.row(8).reshape(1, 3);
            double h33 = bestH.at<double>(2, 2);
            if (std::abs(h33) > 1e-8) {
                bestH = bestH / h33;
            }
        }

        return bestH;
    }

    // 从 H 恢复 3D 旋转与平移，并在数学上消除图像匹配畸变带来的旋转剪切（正交化校正）
    bool poseFromHomography(const cv::Mat& H, ARPose& pose) {
        if (H.empty()) return false;

        // ⚡ 输入矩阵 NaN/Inf 检查
        if (!cv::checkRange(H, true)) return false;

        // G = K^(-1) * H
        if (!cv::checkRange(_cameraMatrixInv, true)) return false;
        cv::Mat G = _cameraMatrixInv * H;

        if (!cv::checkRange(G, true)) return false;

        cv::Mat g1 = G.col(0);
        cv::Mat g2 = G.col(1);
        cv::Mat g3 = G.col(2);

        double norm1 = cv::norm(g1);
        double norm2 = cv::norm(g2);
        if (norm1 < 1e-8 || norm2 < 1e-8) return false;

        // 缩放因子：为了使旋转向量单位化
        double scale = 2.0 / (norm1 + norm2);

        cv::Mat r1 = g1 * scale;
        cv::Mat r2 = g2 * scale;
        cv::Mat t = g3 * scale;

        // r3 = r1 x r2
        cv::Mat r3 = r1.cross(r2);

        // 组装非正交的旋转矩阵 [r1, r2, r3]
        cv::Mat R(3, 3, CV_64F);
        r1.copyTo(R.col(0));
        r2.copyTo(R.col(1));
        r3.copyTo(R.col(2));

        // ⚡ NaN/Inf 拦截：退化矩阵会导致 SVD 崩溃
        if (!cv::checkRange(R, true)) return false;

        // 奇异值正交化校正 (Orthogonalization via SVD)
        cv::Mat w, u, vt;
        cv::SVD::compute(R, w, u, vt);

        // 检查 SVD 分解产物
        if (!cv::checkRange(u, true) || !cv::checkRange(vt, true)) return false;

        cv::Mat R_ortho = u * vt;

        // 修正旋转矩阵的手性方向（右手笛卡尔坐标系）
        if (cv::determinant(R_ortho) < 0) {
            u.col(2) = -u.col(2);
            R_ortho = u * vt;
        }

        // OpenCV 坐标系：X 右，Y 下，Z 前
        // Three.js 坐标系：X 右，Y 上，Z 后
        // 故在矩阵变换中对 Y 轴和 Z 轴对应的行分量进行取反操作，直接输出 WebGL 友好的列主序一维数组
        double r[3][3];
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                r[i][j] = R_ortho.at<double>(i, j);
            }
        }
        double tx = t.at<double>(0, 0);
        double ty = t.at<double>(1, 0);
        double tz = t.at<double>(2, 0);

        // ⚡ NaN/Inf 检查平移向量
        if (std::isnan(tx) || std::isinf(tx) || std::isnan(ty) || std::isinf(ty) || std::isnan(tz) || std::isinf(tz)) return false;

        pose.transformMatrix[0] = static_cast<float>(r[0][0]);
        pose.transformMatrix[1] = static_cast<float>(-r[1][0]);
        pose.transformMatrix[2] = static_cast<float>(-r[2][0]);
        pose.transformMatrix[3] = 0.0f;

        pose.transformMatrix[4] = static_cast<float>(r[0][1]);
        pose.transformMatrix[5] = static_cast<float>(-r[1][1]);
        pose.transformMatrix[6] = static_cast<float>(-r[2][1]);
        pose.transformMatrix[7] = 0.0f;

        pose.transformMatrix[8] = static_cast<float>(r[0][2]);
        pose.transformMatrix[9] = static_cast<float>(-r[1][2]);
        pose.transformMatrix[10] = static_cast<float>(-r[2][2]);
        pose.transformMatrix[11] = 0.0f;

        pose.transformMatrix[12] = static_cast<float>(tx);
        pose.transformMatrix[13] = static_cast<float>(-ty);
        pose.transformMatrix[14] = static_cast<float>(-tz);
        pose.transformMatrix[15] = 1.0f;

        pose.isTracking = true;
        return true;
    }

public:
    ARTracker(int width, int height, float fx, float fy, float cx, float cy) 
        : _width(width), _height(height) {

        // 1. 初始化分配共享像素缓冲区 (RGBA)
        _pixelBuffer = new uint8_t[width * height * 4];

        // 2. 初始化相机内参 K 及内参矩阵逆
        _cameraMatrix = (cv::Mat_<double>(3, 3) << 
            fx,  0, cx,
             0, fy, cy,
             0,  0,  1);
        _cameraMatrixInv = _cameraMatrix.inv();

        // 检查内参矩阵逆是否有效（理论上不应该退化，但防御性编程）
        if (!cv::checkRange(_cameraMatrixInv, true)) {
            _cameraMatrixInv = cv::Mat::eye(3, 3, CV_64F);
        }

        // 3. 极速版 ORB 参数调优：提取 500 个特征点，确保移动端流畅度
        _orb = cv::ORB::create(500, 1.2f, 8, 31, 0, 2, cv::ORB::HARRIS_SCORE, 31, 20);

        // 4. 使用 Hamming 距离并开启交叉匹配（CrossCheck），极大地剔除误匹配点
        _matcher = cv::BFMatcher::create(cv::NORM_HAMMING, true);
    }

    ~ARTracker() {
        if (_pixelBuffer) {
            delete[] _pixelBuffer;
        }
    }

    // 暴露像素缓冲区给 JavaScript
    intptr_t getBufferPointer() {
        return reinterpret_cast<intptr_t>(_pixelBuffer);
    }

    // 初始化注册酒标目标（由 JS 端上传图片后调用）
    bool initTarget(intptr_t templateBufferPtr, int w, int h, float physicalWidth, float physicalHeight) {
        _targetWidth = w;
        _targetHeight = h;
        _physicalWidth = physicalWidth;
        _physicalHeight = physicalHeight;

        uint8_t* rawBuffer = reinterpret_cast<uint8_t*>(templateBufferPtr);

        // RGBA 转为灰度图进行特征点提取
        cv::Mat tempRGBA(h, w, CV_8UC4, rawBuffer);
        cv::Mat tempGray;
        cv::cvtColor(tempRGBA, tempGray, cv::COLOR_RGBA2GRAY);

        _targetKeypoints.clear();
        _orb->detectAndCompute(tempGray, cv::noArray(), _targetKeypoints, _targetDescriptors);

        // 如果特征点太少，说明酒标图案过于单一，不适合追踪
        if (_targetKeypoints.size() < 15) {
            return false;
        }
        return true;
    }

    // 核心更新函数：处理当前相机帧，解算 6 自由度姿态
    ARPose update() {
        ARPose pose;
        pose.isTracking = false;
        pose.transformMatrix.fill(0.0f);

        // 如果还没有初始化酒标模板，直接返回
        if (_targetKeypoints.empty() || _targetDescriptors.empty()) {
            return pose;
        }

        // 1. 封装当前的相机图像 (RGBA -> GRAY)
        cv::Mat frameRGBA(_height, _width, CV_8UC4, _pixelBuffer);
        cv::Mat frameGray;
        cv::cvtColor(frameRGBA, frameGray, cv::COLOR_RGBA2GRAY);

        // 2. 提取当前帧的特征点
        std::vector<cv::KeyPoint> frameKeypoints;
        cv::Mat frameDescriptors;
        _orb->detectAndCompute(frameGray, cv::noArray(), frameKeypoints, frameDescriptors);

        if (frameDescriptors.empty() || frameDescriptors.rows < 15) {
            return pose;
        }

        // 3. 特征匹配
        std::vector<cv::DMatch> matches;
        _matcher->match(_targetDescriptors, frameDescriptors, matches);

        // 4. 建立 2D 物理空间到 2D 图像空间的对应关系
        std::vector<cv::Point2f> srcPoints; // 物理米制坐标
        std::vector<cv::Point2f> dstPoints; // 相机像素坐标

        // 辅助函数：检查 Point2f 是否包含 NaN/Inf
        auto isFinitePoint = [](const cv::Point2f& pt) -> bool {
            return !std::isnan(pt.x) && !std::isinf(pt.x) &&
                   !std::isnan(pt.y) && !std::isinf(pt.y);
        };

        // 检查模板描述子和当前帧描述子是否有效
        if (!cv::checkRange(_targetDescriptors, true)) {
            return pose;
        }
        if (!cv::checkRange(frameDescriptors, true)) {
            return pose;
        }

        // 检查关键点是否有效
        for (const auto& kp : _targetKeypoints) {
            if (!isFinitePoint(kp.pt)) {
                return pose;
            }
        }
        for (const auto& kp : frameKeypoints) {
            if (!isFinitePoint(kp.pt)) {
                return pose;
            }
        }

        // 用于排除重复 match 的集合（防止同一个 trainIdx 被多次匹配 → 减少退化风险）
        std::vector<bool> usedTrainIdx(frameKeypoints.size(), false);

        for (const auto& match : matches) {
            // Hamming 距离小于 64 的视为较优匹配点
            if (match.distance < 64.0f) {
                cv::Point2f targetPt = _targetKeypoints[match.queryIdx].pt;
                cv::Point2f framePt = frameKeypoints[match.trainIdx].pt;

                // 核心几何映射：将模板上的 2D 像素坐标映射到以酒标中心为原点的物理 3D 坐标平面（Z为0）上，由于平面解算只需 X, Y
                float x_phys = (targetPt.x / _targetWidth - 0.5f) * _physicalWidth;
                float y_phys = (0.5f - targetPt.y / _targetHeight) * _physicalHeight; // Y 轴反转对齐到物理上方

                // NaN/Inf 检查
                if (std::isnan(x_phys) || std::isinf(x_phys) ||
                    std::isnan(y_phys) || std::isinf(y_phys) ||
                    !isFinitePoint(targetPt) || !isFinitePoint(framePt)) {
                    continue;
                }

                // 防止重复匹配同一个 trainIdx（减少退化风险）
                int trainIdx = match.trainIdx;
                if (usedTrainIdx[trainIdx]) continue;
                usedTrainIdx[trainIdx] = true;

                srcPoints.push_back(cv::Point2f(x_phys, y_phys));
                dstPoints.push_back(framePt);
            }
        }

        // 至少需要 10 个以上匹配点才能进行 RANSAC 的健壮计算
        if (srcPoints.size() < 10) {
            return pose;
        }

        // 5. 运行 RANSAC 拟合最优单应性投影矩阵 H
        std::vector<int> inliers;
        cv::Mat H = ransacHomography(srcPoints, dstPoints, inliers, 8.0);

        // 6. 内点（匹配正确的数量）达到阈值后重构 3D 姿态
        if (!H.empty() && inliers.size() >= 8) {
            poseFromHomography(H, pose);
        }

        return pose;
    }
};

// Emscripten 注册绑定
EMSCRIPTEN_BINDINGS(orb_tracker_module) {
    emscripten::value_array<std::array<float, 16>>("Float16Array_Custom")
        .element(emscripten::index<0>()).element(emscripten::index<1>())
        .element(emscripten::index<2>()).element(emscripten::index<3>())
        .element(emscripten::index<4>()).element(emscripten::index<5>())
        .element(emscripten::index<6>()).element(emscripten::index<7>())
        .element(emscripten::index<8>()).element(emscripten::index<9>())
        .element(emscripten::index<10>()).element(emscripten::index<11>())
        .element(emscripten::index<12>()).element(emscripten::index<13>())
        .element(emscripten::index<14>()).element(emscripten::index<15>());

    emscripten::value_object<ARPose>("ARPose")
        .field("isTracking", &ARPose::isTracking)
        .field("transformMatrix", &ARPose::transformMatrix);

    emscripten::class_<ARTracker>("ARTracker")
        .constructor<int, int, float, float, float, float>()
        .function("getBufferPointer", &ARTracker::getBufferPointer)
        .function("initTarget", &ARTracker::initTarget)
        .function("update", &ARTracker::update);
}

#include <emscripten.h>
#include <emscripten/bind.h>
#include <opencv2/core.hpp>
#include <opencv2/imgproc.hpp>
#include <opencv2/features2d.hpp>
#include <vector>
#include <array>
#include <algorithm>
#include <cmath>
#include <random>

// 返回给 JS 的姿态数据结构
struct ARPose {
    std::array<float, 16> transformMatrix;
    bool isTracking;
};

class ARTracker {
private:
    uint8_t* _pixelBuffer = nullptr;
    int _width;
    int _height;

    // OpenCV 核心组件
    cv::Mat _cameraMatrix;
    cv::Mat _cameraMatrixInv;
    cv::Ptr<cv::ORB> _orb;
    cv::Ptr<cv::BFMatcher> _matcher;

    // 酒标模板数据
    cv::Mat _targetDescriptors;
    std::vector<cv::KeyPoint> _targetKeypoints;
    int _targetWidth = 0;
    int _targetHeight = 0;

    // 物理参数（单位：米）
    float _physicalWidth = 0.10f;
    float _physicalHeight = 0.15f;

    // 极速 4 点 DLT (Direct Linear Transform) 算法
    cv::Mat computeHomographyDLT(const std::vector<cv::Point2f>& src, const std::vector<cv::Point2f>& dst) {
        cv::Mat A = cv::Mat::zeros(8, 9, CV_64F);
        for (int i = 0; i < 4; ++i) {
            double x = src[i].x;
            double y = src[i].y;
            double u = dst[i].x;
            double v = dst[i].y;

            // 单点 NaN/Inf 拦截
            if (std::isnan(x) || std::isinf(x) || std::isnan(y) || std::isinf(y) ||
                std::isnan(u) || std::isinf(u) || std::isnan(v) || std::isinf(v)) {
                return cv::Mat();
            }

            A.at<double>(2 * i, 0) = -x;
            A.at<double>(2 * i, 1) = -y;
            A.at<double>(2 * i, 2) = -1.0;
            A.at<double>(2 * i, 3) = 0.0;
            A.at<double>(2 * i, 4) = 0.0;
            A.at<double>(2 * i, 5) = 0.0;
            A.at<double>(2 * i, 6) = x * u;
            A.at<double>(2 * i, 7) = y * u;
            A.at<double>(2 * i, 8) = u;

            A.at<double>(2 * i + 1, 0) = 0.0;
            A.at<double>(2 * i + 1, 1) = 0.0;
            A.at<double>(2 * i + 1, 2) = 0.0;
            A.at<double>(2 * i + 1, 3) = -x;
            A.at<double>(2 * i + 1, 4) = -y;
            A.at<double>(2 * i + 1, 5) = -1.0;
            A.at<double>(2 * i + 1, 6) = x * v;
            A.at<double>(2 * i + 1, 7) = y * v;
            A.at<double>(2 * i + 1, 8) = v;
        }

        // NaN/Inf 过滤：退化点对会导致 SVD 崩溃
        if (!cv::checkRange(A, true)) {
            return cv::Mat();
        }

        cv::Mat w, u, vt;
        cv::SVD::compute(A, w, u, vt);

        // SVD 结果可能因数值退化产生 NaN
        if (!cv::checkRange(vt, true)) {
            return cv::Mat();
        }

        cv::Mat H = vt.row(8).reshape(1, 3);
        double h33 = H.at<double>(2, 2);
        if (std::abs(h33) > 1e-8) {
            H = H / h33;
        }
        return H;
    }

    // 自研 RANSAC 鲁棒性单应性过滤算法
    cv::Mat ransacHomography(const std::vector<cv::Point2f>& src, const std::vector<cv::Point2f>& dst, std::vector<int>& bestInliers, double threshold = 8.0) {
        int n = src.size();
        bestInliers.clear();
        if (n < 4) return cv::Mat();

        int maxIterations = 150;
        int bestInliersCount = 0;
        cv::Mat bestH;

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, n - 1);

        for (int iter = 0; iter < maxIterations; ++iter) {
            std::vector<int> idx;
            while (idx.size() < 4) {
                int r = dis(gen);
                if (std::find(idx.begin(), idx.end(), r) == idx.end()) {
                    idx.push_back(r);
                }
            }

            std::vector<cv::Point2f> src_sample(4), dst_sample(4);
            for (int i = 0; i < 4; ++i) {
                src_sample[i] = src[idx[i]];
                dst_sample[i] = dst[idx[i]];
            }

            cv::Mat H = computeHomographyDLT(src_sample, dst_sample);
            if (H.empty()) continue;

            std::vector<int> currentInliers;
            for (int i = 0; i < n; ++i) {
                cv::Mat pt = (cv::Mat_<double>(3, 1) << src[i].x, src[i].y, 1.0);
                cv::Mat projected = H * pt;
                double w = projected.at<double>(2, 0);
                if (std::abs(w) < 1e-7) continue;

                double px = projected.at<double>(0, 0) / w;
                double py = projected.at<double>(1, 0) / w;

                double err = std::sqrt((px - dst[i].x) * (px - dst[i].x) + (py - dst[i].y) * (py - dst[i].y));
                if (err < threshold) {
                    currentInliers.push_back(i);
                }
            }

            if ((int)currentInliers.size() > bestInliersCount) {
                bestInliersCount = (int)currentInliers.size();
                bestInliers = currentInliers;
                bestH = H;
            }
        }

        // 精细化拟合：利用所有内点，重新最小二乘构建更精确的 H 矩阵
        if (bestInliersCount >= 6) {
            int refineRows = std::min(bestInliersCount, 200);
            cv::Mat A = cv::Mat::zeros(refineRows * 2, 9, CV_64F);

            int usedCount = 0;
            for (int i = 0; i < bestInliersCount; ++i) {
                int idx = bestInliers[i];
                double x = src[idx].x;
                double y = src[idx].y;
                double u = dst[idx].x;
                double v = dst[idx].y;

                if (std::isnan(x) || std::isinf(x) || std::isnan(y) || std::isinf(y) ||
                    std::isnan(u) || std::isinf(u) || std::isnan(v) || std::isinf(v)) {
                    continue;
                }

                if (usedCount >= refineRows) break;

                A.at<double>(2 * usedCount, 0) = -x;
                A.at<double>(2 * usedCount, 1) = -y;
                A.at<double>(2 * usedCount, 2) = -1.0;
                A.at<double>(2 * usedCount, 3) = 0.0;
                A.at<double>(2 * usedCount, 4) = 0.0;
                A.at<double>(2 * usedCount, 5) = 0.0;
                A.at<double>(2 * usedCount, 6) = x * u;
                A.at<double>(2 * usedCount, 7) = y * u;
                A.at<double>(2 * usedCount, 8) = u;

                A.at<double>(2 * usedCount + 1, 0) = 0.0;
                A.at<double>(2 * usedCount + 1, 1) = 0.0;
                A.at<double>(2 * usedCount + 1, 2) = 0.0;
                A.at<double>(2 * usedCount + 1, 3) = -x;
                A.at<double>(2 * usedCount + 1, 4) = -y;
                A.at<double>(2 * usedCount + 1, 5) = -1.0;
                A.at<double>(2 * usedCount + 1, 6) = x * v;
                A.at<double>(2 * usedCount + 1, 7) = y * v;
                A.at<double>(2 * usedCount + 1, 8) = v;
                usedCount++;
            }

            if (usedCount < 4) {
                return bestH;
            }

            if (!cv::checkRange(A, true)) {
                return bestH;
            }

            cv::Mat w, u, vt;
            cv::SVD::compute(A.rowRange(0, usedCount * 2), w, u, vt);
            if (!cv::checkRange(u, true) || !cv::checkRange(vt, true)) {
                return bestH;
            }
            bestH = vt.row(8).reshape(1, 3);
            double h33 = bestH.at<double>(2, 2);
            if (std::abs(h33) > 1e-8) {
                bestH = bestH / h33;
            }
        }

        return bestH;
    }

    // 从 H 恢复 3D 旋转与平移
    bool poseFromHomography(const cv::Mat& H, ARPose& pose) {
        if (H.empty()) return false;

        // 输入矩阵 NaN/Inf 检查
        if (!cv::checkRange(H, true)) return false;

        // G = K^(-1) * H
        if (!cv::checkRange(_cameraMatrixInv, true)) return false;
        cv::Mat G = _cameraMatrixInv * H;

        if (!cv::checkRange(G, true)) return false;

        cv::Mat g1 = G.col(0);
        cv::Mat g2 = G.col(1);
        cv::Mat g3 = G.col(2);

        double norm1 = cv::norm(g1);
        double norm2 = cv::norm(g2);
        if (norm1 < 1e-8 || norm2 < 1e-8) return false;

        double scale = 2.0 / (norm1 + norm2);

        cv::Mat r1 = g1 * scale;
        cv::Mat r2 = g2 * scale;
        cv::Mat t = g3 * scale;

        cv::Mat r3 = r1.cross(r2);

        cv::Mat R(3, 3, CV_64F);
        r1.copyTo(R.col(0));
        r2.copyTo(R.col(1));
        r3.copyTo(R.col(2));

        // NaN/Inf 拦截：退化矩阵会导致 SVD 崩溃
        if (!cv::checkRange(R, true)) return false;

        cv::Mat w, u, vt;
        cv::SVD::compute(R, w, u, vt);

        if (!cv::checkRange(u, true) || !cv::checkRange(vt, true)) return false;

        cv::Mat R_ortho = u * vt;

        if (cv::determinant(R_ortho) < 0) {
            u.col(2) = -u.col(2);
            R_ortho = u * vt;
        }

        // OpenCV → Three.js 坐标系转换
        double r[3][3];
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                r[i][j] = R_ortho.at<double>(i, j);
            }
        }
        double tx = t.at<double>(0, 0);
        double ty = t.at<double>(1, 0);
        double tz = t.at<double>(2, 0);

        // NaN/Inf 检查平移向量
        if (std::isnan(tx) || std::isinf(tx) || std::isnan(ty) || std::isinf(ty) || std::isnan(tz) || std::isinf(tz)) return false;

        pose.transformMatrix[0] = static_cast<float>(r[0][0]);
        pose.transformMatrix[1] = static_cast<float>(-r[1][0]);
        pose.transformMatrix[2] = static_cast<float>(-r[2][0]);
        pose.transformMatrix[3] = 0.0f;

        pose.transformMatrix[4] = static_cast<float>(r[0][1]);
        pose.transformMatrix[5] = static_cast<float>(-r[1][1]);
        pose.transformMatrix[6] = static_cast<float>(-r[2][1]);
        pose.transformMatrix[7] = 0.0f;

        pose.transformMatrix[8] = static_cast<float>(r[0][2]);
        pose.transformMatrix[9] = static_cast<float>(-r[1][2]);
        pose.transformMatrix[10] = static_cast<float>(-r[2][2]);
        pose.transformMatrix[11] = 0.0f;

        pose.transformMatrix[12] = static_cast<float>(tx);
        pose.transformMatrix[13] = static_cast<float>(-ty);
        pose.transformMatrix[14] = static_cast<float>(-tz);
        pose.transformMatrix[15] = 1.0f;

        pose.isTracking = true;
        return true;
    }

public:
    ARTracker(int width, int height, float fx, float fy, float cx, float cy) 
        : _width(width), _height(height) {

        _pixelBuffer = new uint8_t[width * height * 4];

        _cameraMatrix = (cv::Mat_<double>(3, 3) << 
            fx,  0, cx,
             0, fy, cy,
             0,  0,  1);
        _cameraMatrixInv = _cameraMatrix.inv();

        if (!cv::checkRange(_cameraMatrixInv, true)) {
            _cameraMatrixInv = cv::Mat::eye(3, 3, CV_64F);
        }

        _orb = cv::ORB::create(500, 1.2f, 8, 31, 0, 2, cv::ORB::HARRIS_SCORE, 31, 20);
        _matcher = cv::BFMatcher::create(cv::NORM_HAMMING, true);
    }

    ~ARTracker() {
        if (_pixelBuffer) {
            delete[] _pixelBuffer;
        }
    }

    intptr_t getBufferPointer() {
        return reinterpret_cast<intptr_t>(_pixelBuffer);
    }

    bool initTarget(intptr_t templateBufferPtr, int w, int h, float physicalWidth, float physicalHeight) {
        _targetWidth = w;
        _targetHeight = h;
        _physicalWidth = physicalWidth;
        _physicalHeight = physicalHeight;

        uint8_t* rawBuffer = reinterpret_cast<uint8_t*>(templateBufferPtr);

        cv::Mat tempRGBA(h, w, CV_8UC4, rawBuffer);
        cv::Mat tempGray;
        cv::cvtColor(tempRGBA, tempGray, cv::COLOR_RGBA2GRAY);

        _targetKeypoints.clear();
        _orb->detectAndCompute(tempGray, cv::noArray(), _targetKeypoints, _targetDescriptors);

        if (_targetKeypoints.size() < 15) {
            return false;
        }
        return true;
    }

    ARPose update() {
        ARPose pose;
        pose.isTracking = false;
        pose.transformMatrix.fill(0.0f);

        if (_targetKeypoints.empty() || _targetDescriptors.empty()) {
            return pose;
        }

        cv::Mat frameRGBA(_height, _width, CV_8UC4, _pixelBuffer);
        cv::Mat frameGray;
        cv::cvtColor(frameRGBA, frameGray, cv::COLOR_RGBA2GRAY);

        std::vector<cv::KeyPoint> frameKeypoints;
        cv::Mat frameDescriptors;
        _orb->detectAndCompute(frameGray, cv::noArray(), frameKeypoints, frameDescriptors);

        if (frameDescriptors.empty() || frameDescriptors.rows < 15) {
            return pose;
        }

        std::vector<cv::DMatch> matches;
        _matcher->match(_targetDescriptors, frameDescriptors, matches);

        std::vector<cv::Point2f> srcPoints;
        std::vector<cv::Point2f> dstPoints;

        // 辅助函数：检查 NaN/Inf
        auto isFinitePoint = [](const cv::Point2f& pt) -> bool {
            return !std::isnan(pt.x) && !std::isinf(pt.x) &&
                   !std::isnan(pt.y) && !std::isinf(pt.y);
        };

        // 检查描述子有效性
        if (!cv::checkRange(_targetDescriptors, true)) return pose;
        if (!cv::checkRange(frameDescriptors, true)) return pose;

        // 检查关键点有效性
        for (const auto& kp : _targetKeypoints) {
            if (!isFinitePoint(kp.pt)) return pose;
        }
        for (const auto& kp : frameKeypoints) {
            if (!isFinitePoint(kp.pt)) return pose;
        }

        // 防止重复匹配同一个 trainIdx
        std::vector<bool> usedTrainIdx(frameKeypoints.size(), false);

        for (const auto& match : matches) {
            if (match.distance < 64.0f) {
                cv::Point2f targetPt = _targetKeypoints[match.queryIdx].pt;
                cv::Point2f framePt = frameKeypoints[match.trainIdx].pt;

                float x_phys = (targetPt.x / _targetWidth - 0.5f) * _physicalWidth;
                float y_phys = (0.5f - targetPt.y / _targetHeight) * _physicalHeight;

                if (std::isnan(x_phys) || std::isinf(x_phys) ||
                    std::isnan(y_phys) || std::isinf(y_phys) ||
                    !isFinitePoint(targetPt) || !isFinitePoint(framePt)) {
                    continue;
                }

                int trainIdx = match.trainIdx;
                if (usedTrainIdx[trainIdx]) continue;
                usedTrainIdx[trainIdx] = true;

                srcPoints.push_back(cv::Point2f(x_phys, y_phys));
                dstPoints.push_back(framePt);
            }
        }

        if (srcPoints.size() < 10) {
            return pose;
        }

        std::vector<int> inliers;
        cv::Mat H = ransacHomography(srcPoints, dstPoints, inliers, 8.0);

        if (!H.empty() && inliers.size() >= 8) {
            poseFromHomography(H, pose);
        }

        return pose;
    }
};

// Emscripten 注册绑定
EMSCRIPTEN_BINDINGS(orb_tracker_module) {
    emscripten::value_array<std::array<float, 16>>("Float16Array_Custom")
        .element(emscripten::index<0>()).element(emscripten::index<1>())
        .element(emscripten::index<2>()).element(emscripten::index<3>())
        .element(emscripten::index<4>()).element(emscripten::index<5>())
        .element(emscripten::index<6>()).element(emscripten::index<7>())
        .element(emscripten::index<8>()).element(emscripten::index<9>())
        .element(emscripten::index<10>()).element(emscripten::index<11>())
        .element(emscripten::index<12>()).element(emscripten::index<13>())
        .element(emscripten::index<14>()).element(emscripten::index<15>());

    emscripten::value_object<ARPose>("ARPose")
        .field("isTracking", &ARPose::isTracking)
        .field("transformMatrix", &ARPose::transformMatrix);

    emscripten::class_<ARTracker>("ARTracker")
        .constructor<int, int, float, float, float, float>()
        .function("getBufferPointer", &ARTracker::getBufferPointer)
        .function("initTarget", &ARTracker::initTarget)
        .function("update", &ARTracker::update);
}

